con:config.script:
log.info("*** "+testRunner.testCase.getLabel() +" is running ***")
// set dates
def today = new Date();
def formatedDay = String.format('%tY-%<tm-%<td', today);
def formatedTime = String.format('%tH:%<tM:%<tS', today);
def formatedToday = formatedDay + " " + formatedTime;
def sendersTime = "sendersTime";
def geoTime = "geoTime";

// set property
def targetStep = testRunner.testCase.getTestStepByName( "Properties" );
targetStep.setPropertyValue( sendersTime, formatedToday);
targetStep.setPropertyValue( geoTime, formatedToday);

