con:response.con:script:
log.info("-- success.Ok_Message --")
log.info("mockService: " + context.getMockRunner().getMockService())
log.info("Project: " + context.getMockRunner().getMockService().getProject())
log.info("Workspace: " + context.getMockRunner().getMockService().getProject().getWorkspace())
// --------------------------
// run MessageAck TestCase
// --------------------------
// xml holder
def groovyUtils = new com.eviware.soapui.support.GroovyUtils(context)
def holder = groovyUtils.getXmlHolder(mockRequest.requestContent)
String messageID = holder.getNodeValue("//*:LOGONEvent.LOGONDataField[*:name='messageID']/*:value");
// setup
String testcase_name = "messageAck_Remote"
String suite_name = "cs-outgoing"
// init context	
project = context.getMockRunner().getMockService().getProject();
testSuite = project.getTestSuiteByName(suite_name);
testCase = testSuite.getTestCaseByName(testcase_name);
testCase_properties = testCase.getTestStepByName("Properties")
// transfer properties
testCase_properties.setPropertyValue("messageID", messageID)
// run test case
runner = testCase.run(new com.eviware.soapui.support.types.StringToObjectMap(), true)

log.info("-- success.Ok_orderDataParallel --")
// --------------------------
// run MessageAck TestCase
// --------------------------
// xml holder
def groovyUtils = new com.eviware.soapui.support.GroovyUtils(context)
def holder = groovyUtils.getXmlHolder(mockRequest.requestContent)

// setup
String testcase_name = "orderDataWithParallel9013_Remote"
String project_name = "Testen"
String suite_name = "MOPEventPort_TestSuite"
// init context	
project = context.getMockRunner().getMockService().getProject().getWorkspace().getProjectByName(project_name)
testSuite = project.getTestSuiteByName(suite_name);
testCase = testSuite.getTestCaseByName(testcase_name);
testCase_properties = testCase.getTestStepByName("Properties")

// transfer properties ( ? may be update properties from external file first? )

// save assID + sessionID
def assID = holder.getNodeValue("//*:LOGONEvent.LOGONDataField[*:name='logonAssignmentID']/*:value");
testCase_properties.setPropertyValue("curr_logonAssignmentID", assID)
def sessionID = holder.getNodeValue("//*:sessionID")
testCase_properties.setPropertyValue("curr_sessionID", sessionID)
// save other fields to properties
def DataFields = ['shippingpointCoordLat','shippingpointCoordLon', 'shippingpointID', 'shipToID', 'shipToCoordLat', 'shipToCoordLon'] as String[]
for (field in DataFields){
	path = "//*:LOGONEvent.LOGONDataField[*:name='" + field + "']/*:value"
	temp = holder.getNodeValue(path)
	log.info(field + ": " + temp)
	testCase_properties.setPropertyValue(field, temp)
}
// loadingPointList properties for loginParallel
String terminalLabel = holder.getNodeValue("//*:LOGONEvent.rfidObjectDataField[*:name='loadingPointList']/*:value/*:rfidObject[1]/*:objectName");
String terminalRFID = holder.getNodeValue("//*:LOGONEvent.rfidObjectDataField[*:name='loadingPointList']/*:value/*:rfidObject[1]/*:rfidTag/*:rfid[1]/*:rfidIdentity");
testCase_properties.setPropertyValue("terminalLabel", terminalLabel)
testCase_properties.setPropertyValue("terminalRFID", terminalRFID)
log.info("terminalLabel, terminalRFID: " + terminalLabel + ", " + terminalRFID)

// run test case
runner = testCase.run(new com.eviware.soapui.support.types.StringToObjectMap(), true)
